-- Candidate fixed historical payment-frame DATA. No settlement, expense right,
-- source issue, account, LOGIN, membership or production execution is granted.
-- Requires Industry firstday/work/wage custody and revocation-fence proposals.
begin;
grant create on schema world_v2 to world_v2_industry_source_owner;
create function world_v2.read_postwar_industry_paid_work_original(p_world text,p_country text,p_facility text,p_run text,p_work_fingerprint text,p_world_version bigint,p_event_sequence bigint,p_seed_fingerprint text,p_admission text)
returns table(world_id text,country_id text,facility_id text,run_id text,work_event_fingerprint text,world_version text,event_sequence text,seed_id text,seed_fingerprint text,admission_ref text,source_ref text,source_raw_sha256 text,from_world_version text,from_event_sequence text,payment_frame_text text,payment_frame_sha256 text)
language plpgsql security definer set search_path=pg_catalog as $$
declare effective name;h record;a world_v2.runtime_opening_admission%rowtype;s world_v2.postwar_industry_first_day_source%rowtype;c world_v2.command_submission%rowtype;r world_v2.command_receipt%rowtype;e world_v2.authoritative_event%rowtype;w world_v2.authoritative_event%rowtype;wc world_v2.command_submission%rowtype;wr world_v2.command_receipt%rowtype;body jsonb;work_body jsonb;command jsonb;event jsonb;transition jsonb;receipt jsonb;batch jsonb;raw text;n bigint;begin
 effective:=case when current_setting('role')='none'then session_user else current_setting('role')::name end;
 if effective<>'world_v2_industry_source_reader'or pg_has_role(session_user,'world_v2_industry_source_owner','MEMBER')or exists(select 1 from pg_roles x where x.rolname=effective and(x.rolsuper or x.rolbypassrls or x.rolcreatedb or x.rolcreaterole or x.rolreplication))then raise exception 'INDUSTRY_PAID_WORK_FIXED_READER_REQUIRED'using errcode='42501';end if;
 if current_setting('transaction_isolation')not in('repeatable read','serializable')or current_setting('transaction_read_only')<>'off'then raise exception 'INDUSTRY_PAID_WORK_HELD_RR_REQUIRED'using errcode='25001';end if;
 if p_world is null or p_country is null or p_facility is null or p_run is null or (p_work_fingerprint is null or p_work_fingerprint!~'^sha256:[a-f0-9]{64}$')or p_seed_fingerprint is null or p_admission is null or p_world_version is null or p_event_sequence is null then raise exception 'INDUSTRY_PAID_WORK_EXACT_SCOPE_REQUIRED'using errcode='22023';end if;
 perform world_v2.lock_postwar_source_revocation_fences(p_world);
 perform set_config('econmind.industry_source_world',p_world,true);
 select x.world_version,x.event_sequence into strict h from world_v2.world_head x where x.world_id=p_world for share;
 if h.world_version<>p_world_version or h.event_sequence<>p_event_sequence then raise exception 'INDUSTRY_PAID_WORK_ACTUAL_HEAD_CHANGED'using errcode='40001';end if;
 a:=world_v2.industry_source_admission(p_world);
 if a.seed_fingerprint is distinct from p_seed_fingerprint or a.admission_ref is distinct from p_admission then raise exception 'INDUSTRY_PAID_WORK_CURRENT_ADMISSION_REQUIRED'using errcode='55000';end if;
 select * into w from world_v2.authoritative_event x where x.world_id=p_world and x.event_fingerprint=p_work_fingerprint and x.event_type='INDUSTRY_FIRST_DAY_WORK_COMPLETED_V1'and x.world_version<=h.world_version;
 if not found then return;end if;
 work_body:=w.canonical_payload::jsonb;
 select * into strict wc from world_v2.command_submission x where x.world_id=p_world and x.command_id=w.causation_command_id and x.command_type='CORE_INDUSTRY_FIRST_DAY_WORK_V1'and x.country_id=p_country and x.office_id is null;
 select * into strict wr from world_v2.command_receipt x where x.world_id=p_world and x.command_id=wc.command_id and x.command_fingerprint=wc.command_fingerprint and x.outcome='COMMITTED'and x.reason_code is null and x.world_version_after=w.world_version and x.world_version_before=wc.expected_world_version and x.world_version_after=x.world_version_before+1 and x.event_ids=jsonb_build_array(w.event_id);
 if work_body->>'facilityId'is distinct from p_facility or work_body->>'runId'is distinct from p_run or work_body->>'countryId'is distinct from p_country or work_body->>'worldId'is distinct from p_world or work_body->>'seedId'is distinct from a.seed_id or work_body->>'seedFingerprint'is distinct from a.seed_fingerprint or work_body->>'admissionRef'is distinct from a.admission_ref then raise exception 'INDUSTRY_PAID_WORK_ACTUAL_WORK_SCOPE_REQUIRED'using errcode='23514';end if;
 select * into strict s from world_v2.postwar_industry_first_day_source x where x.world_id=p_world and x.country_id=p_country and x.facility_id=p_facility and x.source_ref=work_body->'policy'->>'sourceRef'and x.source_sha256=work_body->'policy'->>'sourceRawSha256'and x.seed_id=a.seed_id and x.seed_fingerprint=a.seed_fingerprint and x.admission_ref=a.admission_ref for share;
 if s.source_sha256 is distinct from encode(sha256(convert_to(s.source_text,'UTF8')),'hex')then raise exception 'INDUSTRY_PAID_WORK_IMMUTABLE_SOURCE_HASH_REQUIRED'using errcode='23514';end if;
 select count(*)into n from world_v2.authoritative_event x join world_v2.command_receipt rc on rc.world_id=x.world_id and rc.command_id=x.causation_command_id and rc.outcome='COMMITTED'where x.world_id=p_world and x.event_type='INDUSTRY_OPERATING_WAGE_PAID_V1'and x.canonical_payload::jsonb->>'workEventFingerprint'=p_work_fingerprint and x.world_version<=h.world_version;
 if n=0 then return;end if;if n<>1 then raise exception 'INDUSTRY_PAID_WORK_EXACT_SINGLE_PAYMENT_REQUIRED'using errcode='23514';end if;
 select x.* into strict e from world_v2.authoritative_event x join world_v2.command_receipt rc on rc.world_id=x.world_id and rc.command_id=x.causation_command_id and rc.outcome='COMMITTED'where x.world_id=p_world and x.event_type='INDUSTRY_OPERATING_WAGE_PAID_V1'and x.canonical_payload::jsonb->>'workEventFingerprint'=p_work_fingerprint and x.world_version<=h.world_version;
 body:=e.canonical_payload::jsonb;
 select * into strict c from world_v2.command_submission x where x.world_id=p_world and x.country_id=p_country and x.command_id=e.causation_command_id and x.command_type='CORE_INDUSTRY_OPERATING_WAGE_PAY_V1'and x.office_id is null and x.actor_id=wc.actor_id and x.auth_subject is not distinct from wc.auth_subject;
 select * into strict r from world_v2.command_receipt x where x.world_id=p_world and x.command_id=c.command_id and x.command_fingerprint=c.command_fingerprint and x.outcome='COMMITTED'and x.reason_code is null and x.world_version_before=c.expected_world_version and x.world_version_after=x.world_version_before+1 and x.world_version_after=e.world_version and x.world_version_after>wr.world_version_after and x.event_ids=jsonb_build_array(e.event_id)and x.sim_time=c.sim_time and x.sim_time=e.sim_time;
 if body->>'schemaVersion'is distinct from'industry-operating-wage-paid-v1'or body->'policy'->>'version'is distinct from'INDUSTRY_ACTUAL_COMPLETED_WORK_WAGE_V2'or c.canonical_payload::jsonb->>'policyVersion'is distinct from'INDUSTRY_ACTUAL_COMPLETED_WORK_WAGE_V2'or body->>'workEventId'is distinct from w.event_id or body->>'workCommandFingerprint'is distinct from wc.command_fingerprint or body->'source'->>'worldId'is distinct from p_world or body->'source'->>'countryId'is distinct from p_country or body->'source'->>'facilityId'is distinct from p_facility or body->'source'->>'runId'is distinct from p_run or body->'source'->>'operatorId'is distinct from work_body->>'operatorId'or body->'source'->>'seedFingerprint'is distinct from a.seed_fingerprint or body->'source'->>'admissionRef'is distinct from a.admission_ref or body->>'paidAmount'!~'^(0|[1-9][0-9]*)(\.[0-9]*[1-9])?$'or(body->>'paidAmount')::numeric<=0 then raise exception 'INDUSTRY_PAID_WORK_POSITIVE_V2_ACTUAL_PAYMENT_REQUIRED'using errcode='23514';end if;
 if exists(select 1 from world_v2.inventory_posting x where x.world_id=p_world and x.causation_command_id=c.command_id)or(select count(*)from world_v2.financial_posting_batch x where x.world_id=p_world and x.causation_command_id=c.command_id)<>1 then raise exception 'INDUSTRY_PAID_WORK_EXACT_ONE_REAL_BATCH_REQUIRED'using errcode='23514';end if;
 select x.canonical_payload::jsonb||jsonb_build_object('fingerprint',x.batch_fingerprint)into strict batch from world_v2.financial_posting_batch x where x.world_id=p_world and x.causation_command_id=c.command_id and x.canonical_payload=world_v2.canonical_json(x.canonical_payload::jsonb)and x.batch_fingerprint='sha256:'||encode(sha256(convert_to('SHA-256'||chr(10)||x.canonical_payload,'UTF8')),'hex')and x.world_version_before=r.world_version_before and x.world_version_after=r.world_version_after and x.event_ids=r.event_ids and x.sim_time=r.sim_time and octet_length(x.canonical_payload)<=65536;
 command:=jsonb_build_object('actorId',c.actor_id,'authSubject',c.auth_subject::text,'commandId',c.command_id,'commandType',c.command_type,'correlationId',c.correlation_id,'countryId',c.country_id,'expectedWorldVersion',c.expected_world_version::text,'idempotencyKey',c.idempotency_key,'officeId',c.office_id,'canonicalPayload',c.canonical_payload,'schemaVersion',c.schema_version,'simTime',c.sim_time::text,'submittedAtReal',to_char(c.submitted_at_real at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'worldId',p_world,'fingerprint',c.command_fingerprint,'payloadHash',c.payload_sha256);
 event:=jsonb_build_object('causationCommandId',e.causation_command_id,'correlationId',e.correlation_id,'correctsEventId',e.corrects_event_id,'eventId',e.event_id,'eventType',e.event_type,'canonicalPayload',e.canonical_payload,'schemaVersion',e.schema_version,'sequence',e.event_sequence::text,'simTime',e.sim_time::text,'worldId',p_world,'worldVersion',e.world_version::text,'fingerprint',e.event_fingerprint,'payloadHash',e.payload_sha256,'recordedAtReal',to_char(e.recorded_at_real at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
 transition:=jsonb_build_object('schemaVersion','authoritative-transition-v1','transitionId',c.command_id,'worldId',p_world,'commandId',c.command_id,'commandFingerprint',c.command_fingerprint,'worldVersionBefore',r.world_version_before::text,'worldVersionAfter',r.world_version_after::text,'eventIds',r.event_ids,'events',jsonb_build_array(event));
 receipt:=jsonb_build_object('schemaVersion',r.schema_version,'worldId',p_world,'commandId',r.command_id,'idempotencyKey',r.idempotency_key,'commandFingerprint',r.command_fingerprint,'outcome',r.outcome,'reasonCode',r.reason_code,'transitionId',r.transition_id,'worldVersionBefore',r.world_version_before::text,'worldVersionAfter',r.world_version_after::text,'simTime',r.sim_time::text,'eventIds',r.event_ids,'recordedAtReal',to_char(r.recorded_at_real at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
 raw:=world_v2.canonical_json(jsonb_build_object('command',command,'transition',transition,'events',jsonb_build_array(event),'receipt',receipt,'financialPostingBatches',jsonb_build_array(batch),'inventoryPostings','[]'::jsonb));
 if octet_length(raw)>262144 then raise exception 'INDUSTRY_PAID_WORK_FRAME_256K_BOUND'using errcode='54000';end if;
 return query select p_world,p_country,p_facility,p_run,p_work_fingerprint,h.world_version::text,h.event_sequence::text,a.seed_id,a.seed_fingerprint,a.admission_ref,s.source_ref,s.source_sha256,r.world_version_before::text,(e.event_sequence-1)::text,raw,'sha256:'||encode(sha256(convert_to('SHA-256'||chr(10)||raw,'UTF8')),'hex');
end;$$;
alter function world_v2.read_postwar_industry_paid_work_original(text,text,text,text,text,bigint,bigint,text,text)owner to world_v2_industry_source_owner;
revoke all on function world_v2.read_postwar_industry_paid_work_original(text,text,text,text,text,bigint,bigint,text,text)from public;
grant execute on function world_v2.read_postwar_industry_paid_work_original(text,text,text,text,text,bigint,bigint,text,text)to world_v2_industry_source_reader;
revoke create on schema world_v2 from world_v2_industry_source_owner;
commit;
